def seed_launch_content(conn):
    now = datetime.now(UTC).isoformat()
    for title, deck, body, category, author, presidents, topics, sources, featured in LAUNCH_STORIES:
        slug = ''.join(c.lower() if c.isalnum() else '-' for c in title)
        slug = '-'.join(filter(None, slug.split('-')))
        row = conn.execute('SELECT id FROM stories WHERE slug=?', (slug,)).fetchone()
        values = (title, deck, body, category, author, presidents, topics, sources, 'Verified', 'Linked or original editorial summary', 'Published', now, featured, now)
        if row:
            conn.execute('UPDATE stories SET title=?,deck=?,body=?,category=?,author=?,president_tags=?,topic_tags=?,source_notes=?,fact_check_status=?,rights_status=?,publication_status=?,published_at=?,featured=?,updated_at=? WHERE id=?', values + (row[0],))
        else:
            conn.execute('INSERT INTO stories(slug,title,deck,body,category,author,president_tags,topic_tags,source_notes,fact_check_status,rights_status,publication_status,published_at,featured,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', (slug,) + values[:-1] + (now, now))
